"""Write the routing proof crate into a temporary repository."""
from pathlib import Path


PACKAGE = 'aws-routing-proof'

FILES: dict[str, str] = {
    'Cargo.toml': '''[package]
name = "aws-routing-proof"
version = "0.1.0"
edition = "2024"
publish = false

[workspace]
''',
    'Cargo.lock': '''# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 4

[[package]]
name = "aws-routing-proof"
version = "0.1.0"
''',
    'flake.nix': '''{
  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";

  outputs = { nixpkgs, ... }: {
    devShells.x86_64-linux.default = nixpkgs.legacyPackages.x86_64-linux.mkShellNoCC {
      # The proof checks the host tools without another repository's shell.
      shellHook = ''
        export PATH="$HOME/.cargo/bin:/run/current-system/sw/bin:$PATH"
      '';
    };
  };
}
''',
    'flake.lock': '''{
  "nodes": {
    "nixpkgs": {
      "locked": {
        "lastModified": 1789009968,
        "narHash": "sha256-GB16oaxpsrnGNnGIE+0uYBqMRzB9X6FYDUvjvnJAYew=",
        "owner": "NixOS",
        "repo": "nixpkgs",
        "rev": "d58a46e3bc02d91ebe04667f8397752a749c0024",
        "type": "github"
      },
      "original": {
        "owner": "NixOS",
        "ref": "nixos-26.05",
        "repo": "nixpkgs",
        "type": "github"
      }
    },
    "root": {
      "inputs": {
        "nixpkgs": "nixpkgs"
      }
    }
  },
  "root": "root",
  "version": 7
}
''',
    '.gitignore': '''/target/
''',
    'src/lib.rs': '''#[cfg(test)]
mod tests {
    #[test]
    fn compiler_runs_in_the_target_environment() {
        let output = std::process::Command::new("rustc")
            .arg("-V")
            .output()
            .expect("The compiler must be on PATH");
        assert!(output.status.success(), "The compiler must run");
        assert!(String::from_utf8(output.stdout)
            .expect("The version must be UTF-8")
            .starts_with("rustc "));
    }
}
''',
}


def write_crate(directory: Path) -> None:
    """Write the six crate files without changing their contents."""
    for name, content in FILES.items():
        path = directory / name
        path.parent.mkdir(parents=True, exist_ok=True)
        _ = path.write_text(content, encoding='utf-8')
